import sys;sys.path.insert(0,'..')
from gcommon import *
SRC=srcs([GD('gittutorial'),GD('git-status'),GD('git-diff'),GD('git-commit'),GD('git-log'),GD('gitignore'),GD('git-mv'),GD('git-rm'),('https://www.odoo.com/documentation/20.0/contributing/development/git_guidelines.html','Odoo 20 – Git guidelines')])
CODE_COURSE='''from odoo import fields, models


class VincCourse(models.Model):
    _name = 'vinc.course'
    _description = 'Khóa học'

    name = fields.Char(required=True)'''
def build(vi):
    t=lambda a,b:a if vi else b
    sb=SB('a02');sb.q('mkdir -p vinc_course/models');sb.cd('vinc_course');sb.q('git init -q')
    sb.w('__manifest__.py',"{\n    'name': 'Vinc Course',\n    'version': '1.0',\n    'depends': ['base'],\n    'data': [],\n    'license': 'LGPL-3',\n}\n")
    sb.w('__init__.py','from . import models\n');sb.w('models/__init__.py','from . import course\n');sb.w('models/course.py',CODE_COURSE+'\n')
    tree=pre('vinc_course/\n├── __init__.py\n├── __manifest__.py\n└── models/\n    ├── __init__.py\n    └── course.py')
    A=sb.P('git status','git add .','git status -s','git commit -m "[ADD] vinc_course: khung module và model vinc.course"','git log --oneline')
    B=sb.P("echo \"    hours = fields.Integer(string='Số giờ')\" >> models/course.py",'git status -s','git diff','git add models/course.py','git status -s','git diff','git diff --staged','git commit -m "[IMP] vinc_course: thêm trường số giờ"')
    C=sb.P('git log --stat --oneline','git show --stat HEAD','git log --oneline -n 1')
    sb.q('mkdir -p models/__pycache__ && echo x > models/__pycache__/course.cpython-312.pyc && echo "admin_passwd = secret" > odoo.conf && echo log > odoo.log')
    D=sb.P('git status -s','printf "__pycache__/\\n*.pyc\\n*.log\\nodoo.conf\\n.venv/\\n" > .gitignore','git status -s','git check-ignore -v odoo.conf models/__pycache__/course.cpython-312.pyc','git add .gitignore','git commit -m "[ADD] vinc_course: .gitignore"')
    sb.w('README.md','# vinc_course\n\nModule quản lý khóa học.\n');sb.q('git add README.md;git commit -qm "[ADD] vinc_course: README"')
    G=sb.P('git mv README.md README.rst','git status -s','git commit -m "[MOV] vinc_course: đổi README.md thành README.rst"','git log --oneline --follow -- README.rst')
    e=SB('a02e');e.q('mkdir vinc_course');e.cd('vinc_course');e.q('git init -q');e.w('models.py','x = 1\n');e.w('odoo.conf','admin_passwd = secret\n');e.q('git add .;git commit -qm "[ADD] vinc_course: khung"')
    E=e.P('printf "odoo.conf\\n" > .gitignore','echo "db_name = vinc" >> odoo.conf','git status -s','git rm --cached odoo.conf','git add .gitignore','git status -s','git commit -m "[FIX] vinc_course: bỏ odoo.conf khỏi repo"','git status -s')
    F=e.P('echo "# ghi chú" > NOTE.md','echo "y = 2" >> models.py','git commit -am "[IMP] vinc_course: sửa models"','git status -s')
    o=summ((t('Tóm tắt nhanh','In short'),t('<strong>Hằng ngày bạn chỉ lặp một vòng: sửa file → <code>git status</code> → <code>git diff</code> → <code>git add</code> → <code>git commit</code>.</strong> Bài này chạy vòng đó trên module <code>vinc_course</code>: đọc ký hiệu của <code>git status -s</code>, phân biệt <code>git diff</code> với <code>git diff --staged</code>, viết commit theo quy ước <code>[TAG] module:</code> của Odoo, xem lại bằng <code>git log</code>/<code>git show</code> và dùng <code>.gitignore</code> để <code>__pycache__</code>, <code>odoo.conf</code> không lọt vào repo.','<strong>Day to day you repeat one loop: edit files → <code>git status</code> → <code>git diff</code> → <code>git add</code> → <code>git commit</code>.</strong> This part runs that loop on the <code>vinc_course</code> module: reading the symbols of <code>git status -s</code>, telling <code>git diff</code> from <code>git diff --staged</code>, writing commits in Odoo\'s <code>[TAG] module:</code> style, reviewing them via <code>git log</code> and <code>git show</code>, and using <code>.gitignore</code> so <code>__pycache__</code> and <code>odoo.conf</code> never reach the repo.')))
    o+=h2('vong-lap',t('Vòng lặp hằng ngày trên module vinc_course','The daily loop on the vinc_course module'))
    o+=p(t('Giả sử bạn vừa dựng khung module với cấu trúc dưới đây (nội dung từng file như series Odoo). Repo đã <code>git init</code> nhưng chưa có commit nào, nên <code>git status</code> liệt kê mọi thứ là <em>untracked</em>: Git thấy file nhưng chưa theo dõi.','Suppose you have just built the module skeleton below (file contents as in the Odoo series). The repo has been <code>git init</code>-ed but has no commits yet, so <code>git status</code> lists everything as <em>untracked</em>: Git sees the files but is not following them.'))
    o+=tree+pre(CODE_COURSE)
    o+=p(t('Dùng <code>git add .</code> để đưa tất cả vào staging rồi commit. Với lần đầu tiên thì như vậy là ổn, nhưng từ lần sau hãy tập thói quen <strong>xem <code>git status</code> trước khi <code>add .</code></strong> để chắc không kéo theo file rác.','Use <code>git add .</code> to stage everything and then commit. That is fine for the very first time, but from now on make it a habit to <strong>read <code>git status</code> before <code>add .</code></strong> so you do not drag junk files along.'))
    o+=A
    o+=p(t('Dòng đầu của commit message (<code>[ADD] vinc_course: ...</code>) là thông lệ trong các repo Odoo; ta sẽ nói kỹ ở bài 10. Hiện tại chỉ cần nhớ: <code>-m</code> cho thông điệp một dòng, và mỗi commit nên làm đúng một việc.','The first line of the message (<code>[ADD] vinc_course: ...</code>) follows a convention common in Odoo repositories; part 10 covers it in depth. For now just remember: <code>-m</code> gives a one-line message, and each commit should do exactly one thing.'))
    o+=h2('status',t('Đọc git status -s như đọc bảng điểm','Reading git status -s'))
    o+=p(t('Bản đầy đủ của <code>git status</code> dễ đọc cho người mới, nhưng bản rút gọn <code>-s</code> (<code>--short</code>) nhanh hơn nhiều khi dự án lớn. Mỗi dòng có hai cột ký hiệu: cột trái là trạng thái trong staging, cột phải là trạng thái trong thư mục làm việc.','The full <code>git status</code> is friendly to newcomers, but the short form <code>-s</code> (<code>--short</code>) is much quicker on a large project. Each line has two symbol columns: the left one is the state in staging, the right one the state in the working tree.'))
    o+=tbl([t('Hiển thị','Shown'),t('Ý nghĩa','Meaning'),t('Làm gì tiếp','Next step')],[
        ['<code>?? file</code>',t('File mới, Git chưa theo dõi','New file Git is not tracking'),t('<code>git add</code> nếu cần commit, hoặc thêm vào <code>.gitignore</code>','<code>git add</code> if it belongs, otherwise add it to <code>.gitignore</code>')],
        ['<code>A&nbsp;&nbsp;file</code>',t('File mới đã vào staging','New file already staged'),t('Sẵn sàng commit','Ready to commit')],
        ['<code>&nbsp;M file</code>',t('Đã sửa trong thư mục làm việc, chưa staging','Edited on disk but not staged'),t('<code>git diff</code> để xem, <code>git add</code> để chọn','<code>git diff</code> to review, <code>git add</code> to stage')],
        ['<code>M&nbsp;&nbsp;file</code>',t('Đã sửa và đã staging','Modified and staged'),t('Sẵn sàng commit','Ready to commit')],
        ['<code>&nbsp;D file</code>',t('Đã xóa trong thư mục làm việc','Deleted in the working tree'),t('<code>git add</code> hoặc <code>git rm</code> để ghi nhận việc xóa','<code>git add</code> or <code>git rm</code> to record the deletion')]])
    o+=h2('diff',t('Xem mình đã đổi gì: git diff và git diff --staged','Seeing what changed: git diff and git diff --staged'))
    o+=p(t('Hai lệnh này hay bị nhầm. <code>git diff</code> (không cờ) so thư mục làm việc với staging, tức là những thay đổi <strong>chưa</strong> được <code>add</code>. <code>git diff --staged</code> (đồng nghĩa với <code>--cached</code>) so staging với commit gần nhất, tức là đúng thứ sẽ vào commit tiếp theo. Hãy thêm trường <code>hours</code> vào model và theo dõi:','These two are easy to mix up. <code>git diff</code> (no flags) compares the working tree with staging, meaning changes that have <strong>not</strong> been added yet. <code>git diff --staged</code> (a synonym of <code>--cached</code>) compares staging with the latest commit, meaning exactly what the next commit will contain. Let us add an <code>hours</code> field to the model and watch:'))
    o+=B
    o+=p(t('Cách đọc: dòng bắt đầu bằng <code>+</code> là dòng thêm, <code>-</code> là dòng xóa, dòng <code>@@</code> cho biết vị trí trong file. Để ý lần <code>git diff</code> thứ hai không in gì: mọi thay đổi đã nằm trong staging nên không còn khác biệt giữa thư mục làm việc và staging. Thói quen tốt trước mỗi lần commit là chạy <code>git diff --staged</code> để tự review lần cuối, giống như đọc lại email trước khi gửi.','How to read it: a line starting with <code>+</code> was added, <code>-</code> was removed, and the <code>@@</code> line gives the position in the file. Notice the second <code>git diff</code> prints nothing: every change is already in staging, so disk and staging no longer differ. A good habit before each commit is to run <code>git diff --staged</code> as a last self-review, like rereading an email before sending it.'))
    o+=h2('log',t('Đọc lại lịch sử: git log và git show','Reading history: git log and git show'))
    o+=C
    o+=p(t('<code>git log</code> liệt kê commit từ mới đến cũ; <code>--oneline</code> rút mỗi commit còn một dòng, <code>--stat</code> thêm thống kê file đã đổi, <code>-n 1</code> giới hạn số commit. <code>git show</code> in chi tiết một commit (mặc định là <code>HEAD</code>, commit mới nhất): tác giả, thời gian, lời nhắn và thay đổi.','<code>git log</code> lists commits from newest to oldest; <code>--oneline</code> shrinks each to one line, <code>--stat</code> adds a summary of the files changed and <code>-n 1</code> limits how many commits are shown. <code>git show</code> prints the details of one commit (by default <code>HEAD</code>, the latest): author, time, message and changes.'))
    o+=tbl([t('Lệnh','Command'),t('Tác dụng','What it does')],[
        ['<code>git log --oneline</code>',t('Mỗi commit một dòng: mã ngắn + tiêu đề','One line per commit: short hash + title')],
        ['<code>git log -p -- đường/dẫn</code>',t('Xem thay đổi chi tiết của riêng một file','Detailed changes for a single file')],
        ['<code>git log --author="An"</code>',t('Lọc theo tác giả','Filter by author')],
        ['<code>git log --since="1 week ago"</code>',t('Lọc theo thời gian','Filter by time')],
        ['<code>git show &lt;mã&gt;</code>',t('Chi tiết một commit bất kỳ','Details of any commit')]])
    o+=h2('gitignore',t('.gitignore: giữ file rác và file bí mật ngoài repo','.gitignore: keeping junk and secrets out of the repo'))
    o+=p(t('Khi chạy Odoo, Python tự sinh thư mục <code>__pycache__</code>, server ghi file log, và bạn có thể có file cấu hình <code>odoo.conf</code> chứa <code>admin_passwd</code>. Không thứ nào nên nằm trong repo: rác làm lịch sử nhiễu, còn mật khẩu một khi đã lên GitLab thì nhiều người nhìn thấy. File <code>.gitignore</code> ở thư mục gốc repo liệt kê mẫu tên mà Git sẽ lờ đi:','When you run Odoo, Python generates <code>__pycache__</code> folders, the server writes log files, and you may have an <code>odoo.conf</code> holding <code>admin_passwd</code>. None of these belongs in the repo: junk clutters history, and a password that reaches GitLab is seen by many people. A <code>.gitignore</code> file at the repo root lists name patterns Git will ignore:'))
    o+=D
    o+=p(t('<code>git check-ignore -v</code> cho biết file nào bị luật nào chặn (cột đầu là <code>file:dòng:mẫu</code>), rất tiện khi bạn không hiểu vì sao một file không hiện trong <code>status</code>. Nhớ <strong>commit cả chính <code>.gitignore</code></strong> để cả nhóm dùng chung luật.','<code>git check-ignore -v</code> shows which rule blocks which file (the first column is <code>file:line:pattern</code>), which is handy when you wonder why a file never shows up in <code>status</code>. Remember to <strong>commit <code>.gitignore</code> itself</strong> so the whole team shares the rules.'))
    o+=tbl([t('Mẫu','Pattern'),t('Khớp với','Matches')],[['<code>*.pyc</code>',t('Mọi file có đuôi <code>.pyc</code>','Every file ending in <code>.pyc</code>')],['<code>__pycache__/</code>',t('Thư mục tên <code>__pycache__</code> (dấu <code>/</code> cuối chỉ khớp thư mục)','Directories named <code>__pycache__</code> (the trailing <code>/</code> matches directories only)')],['<code>odoo.conf</code>',t('File tên đó ở mọi cấp thư mục','A file of that name at any depth')],['<code>!keep.log</code>',t('Dấu <code>!</code> đảo ngược: không bỏ qua file này','A leading <code>!</code> negates: do not ignore this file')],['<code># ghi chú</code>',t('Dòng bắt đầu bằng <code>#</code> là chú thích','A line starting with <code>#</code> is a comment')]])
    o+=h2('trong-odoo',t('Gợi ý .gitignore cho dự án Odoo','A starter .gitignore for an Odoo project'))
    o+=tbl([t('Mẫu','Pattern'),t('Vì sao nên bỏ qua','Why ignore it')],[
        ['<code>__pycache__/</code>, <code>*.pyc</code>',t('Bytecode Python tự sinh, khác nhau giữa máy','Auto-generated Python bytecode that differs per machine')],
        ['<code>.venv/</code>',t('Môi trường ảo (bài 1 series Python): dựng lại được từ <code>requirements.txt</code>','The virtual environment (part 1 of the Python series): rebuildable from <code>requirements.txt</code>')],
        ['<code>odoo.conf</code>, <code>.env</code>',t('Chứa mật khẩu và API key; commit file mẫu <code>odoo.conf.example</code> thay thế','Hold passwords and API keys; commit a sample <code>odoo.conf.example</code> instead')],
        ['<code>*.log</code>',t('Log chạy server, lớn và đổi liên tục','Server logs: large and constantly changing')],
        ['<code>.idea/</code>, <code>.vscode/</code>',t('Cấu hình riêng của editor mỗi người','Each person\'s own editor settings')]])
    o+=h2('commit-tot',t('Một commit tốt trông như thế nào','What a good commit looks like'))
    o+=p(t('Git không ép bạn viết gì trong lời nhắn, nhưng sáu tháng sau chính bạn sẽ cảm ơn (hoặc trách) lời nhắn đó khi tìm vì sao một dòng code tồn tại. Hướng dẫn Git của Odoo gợi ý tiêu đề khoảng dưới 50 ký tự, mô tả lý do thay đổi chứ không chỉ liệt kê thao tác, và tránh những tiêu đề chung chung như “bugfix” hay “improvements”. Một vài so sánh trên module của chúng ta:','Git does not force any message on you, but six months later you will thank (or blame) that message when you hunt for why a line exists. Odoo\'s Git guidelines suggest a title of roughly under 50 characters, a body that explains the reason for the change rather than just listing actions, and avoiding vague titles like “bugfix” or “improvements”. A few comparisons on our module:'))
    o+=tbl([t('Tránh','Avoid'),t('Nên viết','Prefer')],[['<code>update</code>','<code>[IMP] vinc_course: thêm trường số giờ cho khóa học</code>'],['<code>fix bug</code>','<code>[FIX] vinc_course: không cho tạo hai khóa trùng mã</code>'],['<code>sửa nhiều thứ</code>',t('Tách thành từng commit, mỗi commit một việc','Split into separate commits, one job each')]])
    o+=p(t('Quy tắc thực dụng: nếu bạn không thể mô tả commit trong một câu mà không dùng chữ “và”, rất có thể nó đang làm hai việc và nên tách bằng cách <code>git add</code> từng file. Khi cần viết nhiều dòng, bỏ cờ <code>-m</code> để Git mở trình soạn thảo bạn đã chọn ở bài 1 (<code>core.editor</code>): dòng đầu là tiêu đề, cách một dòng trống rồi tới phần mô tả.','A practical rule: if you cannot describe a commit in one sentence without the word “and”, it probably does two jobs and should be split by running <code>git add</code> file by file. When you need several lines, drop the <code>-m</code> flag so Git opens the editor you chose in part 1 (<code>core.editor</code>): the first line is the title, then a blank line, then the description.'))
    o+=h2('doi-ten',t('Đổi tên và xóa file đúng cách','Renaming and deleting files properly'))
    o+=p(t('Git không lưu “đổi tên” như một thao tác riêng; nó so nội dung rồi tự nhận ra file đã được chuyển. Dù vậy dùng <code>git mv</code> và <code>git rm</code> giúp thay đổi vào staging ngay, đỡ một bước <code>git add</code>. Hướng dẫn của Odoo còn nhắc: khi chuyển file (tag <code>[MOV]</code>), đừng sửa nội dung cùng lúc, nếu không Git có thể mất dấu lịch sử của file.','Git does not store “rename” as a separate operation; it compares content and recognises that a file moved. Still, <code>git mv</code> and <code>git rm</code> put the change straight into staging, saving a <code>git add</code>. Odoo\'s guidelines add a warning: when moving files (the <code>[MOV]</code> tag), do not change their content at the same time, or Git may lose track of the file\'s history.'))
    o+=G
    o+=p(t('Ký hiệu <code>R</code> là rename. Cờ <code>--follow</code> của <code>git log</code> đi theo file qua lần đổi tên, nên bạn vẫn thấy lịch sử cũ của <code>README.md</code>.','The <code>R</code> symbol stands for rename. The <code>--follow</code> flag of <code>git log</code> follows the file across the rename, so you still see the earlier history of <code>README.md</code>.'))
    o+=call(t('Lỗi hay gặp khi mới học','Common beginner mistakes'),[
        t('<strong>Thêm <code>.gitignore</code> rồi mà file vẫn hiện <code>M</code>.</strong> <code>.gitignore</code> chỉ áp dụng cho file <em>chưa</em> được theo dõi; file đã commit từ trước vẫn bị theo dõi. Tài liệu <code>gitignore</code> hướng dẫn dùng <code>git rm --cached</code> để dừng theo dõi mà vẫn giữ file trên đĩa. Minh họa với <code>odoo.conf</code> lỡ commit từ đầu:','<strong>Added <code>.gitignore</code> but the file still shows <code>M</code>.</strong> <code>.gitignore</code> only applies to files that are <em>not yet</em> tracked; a file committed earlier stays tracked. The <code>gitignore</code> documentation points to <code>git rm --cached</code> to stop tracking while keeping the file on disk. Here it is with an <code>odoo.conf</code> committed by mistake at the start:')
        ,E,t('<strong>Mật khẩu đã commit thì xóa file chưa đủ.</strong> Commit xóa chỉ là một commit mới; nội dung cũ vẫn nằm trong lịch sử. Nếu bí mật đã được đẩy lên GitLab, hãy đổi mật khẩu/khóa đó ngay, rồi nhờ quản trị viên xử lý lịch sử.','<strong>Deleting a committed password is not enough.</strong> The delete is just a new commit; the old content stays in history. If the secret was pushed to GitLab, rotate that password or key at once, then ask an admin to deal with the history.')
        ,t('<strong><code>git commit -a</code> không lấy file mới.</strong> Cờ <code>-a</code> chỉ tự staging file đã theo dõi (đã sửa hoặc xóa); tài liệu nói rõ file chưa được Git biết đến không bị ảnh hưởng. Trong ví dụ, <code>NOTE.md</code> vẫn còn <code>??</code> sau commit:','<strong><code>git commit -a</code> does not take new files.</strong> The <code>-a</code> flag only stages tracked files (modified or deleted); the documentation states files Git has not been told about are not affected. In the example, <code>NOTE.md</code> still shows <code>??</code> after the commit:')
        ,F,t('<strong><code>git add .</code> mà không nhìn <code>status</code>.</strong> Bạn dễ kéo cả file tạm, dump database hay ảnh chụp màn hình vào commit. Hãy <code>git status -s</code> trước, rồi <code>git add</code> đích danh từng file hoặc thư mục.','<strong><code>git add .</code> without looking at <code>status</code>.</strong> You easily sweep temp files, database dumps or screenshots into a commit. Run <code>git status -s</code> first, then <code>git add</code> specific files or folders.')])
    o+=h2('tong-ket',t('Tổng kết','Summary'))
    o+=ul([t('Vòng lặp: sửa → <code>status</code> → <code>diff</code> → <code>add</code> → <code>commit</code>.','The loop: edit → <code>status</code> → <code>diff</code> → <code>add</code> → <code>commit</code>.'),t('<code>git diff</code> xem thay đổi chưa staging; <code>git diff --staged</code> xem thứ sẽ vào commit.','<code>git diff</code> shows unstaged changes; <code>git diff --staged</code> shows what will be committed.'),t('<code>git log --oneline</code> và <code>git show</code> để đọc lịch sử.','<code>git log --oneline</code> and <code>git show</code> read the history.'),t('<code>.gitignore</code> chỉ tác dụng với file chưa theo dõi; lỡ commit thì dùng <code>git rm --cached</code>.','<code>.gitignore</code> only affects untracked files; if you committed by mistake use <code>git rm --cached</code>.'),t('Mật khẩu đã vào lịch sử thì phải đổi mật khẩu, không chỉ xóa file.','A password that entered history must be changed, not just deleted.')])
    o+=p(t('Bạn đã commit được trên một đường thẳng. Nhưng làm việc nhóm nghĩa là nhiều việc chạy song song: một người sửa model, người khác làm báo cáo. Bài tiếp theo giới thiệu <strong>nhánh</strong> để mỗi việc có đường đi riêng, rồi <strong>merge</strong> để gộp lại.','You can now commit along a straight line. But teamwork means several things in parallel: one person edits the model while another builds a report. The next part introduces <strong>branches</strong> so each task gets its own path, then <strong>merging</strong> to bring them back together.'))
    o+=cta(vi,CTA)
    o+='\n'+I+'<h2 id="faq">'+t('Câu hỏi thường gặp','Frequently asked questions')+'</h2>\n'+I+'{FAQ}\n'
    o+='\n'+I+'<h2 id="nguon">'+t('Nguồn tham khảo','References')+'</h2>\n'+SRC
    return o
write('.',build(True),build(False))
